--

CREATE TABLE public.health_entry (
    ts timestamp with time zone CONSTRAINT service_health_ts_not_null NOT NULL,
    service text CONSTRAINT service_health_service_not_null NOT NULL,
    ok boolean CONSTRAINT service_health_ok_not_null NOT NULL,
    latency_ms double precision CONSTRAINT service_health_latency_ms_not_null NOT NULL,
    error text DEFAULT ''::text CONSTRAINT service_health_error_not_null NOT NULL,
    generated boolean DEFAULT false CONSTRAINT service_health_generated_not_null NOT NULL,
    mcp boolean DEFAULT false CONSTRAINT service_health_mcp_not_null NOT NULL,
    active boolean DEFAULT true CONSTRAINT service_health_active_not_null NOT NULL,
    session_id uuid NOT NULL,
    id uuid DEFAULT uuidv7() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: health_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.health_mv AS
 SELECT date_trunc('hour'::text, ts) AS date_hour,
    service,
    (count(*))::integer AS check_count,
    (count(*) FILTER (WHERE (ok = true)))::integer AS ok_count,
    (count(*) FILTER (WHERE (ok = false)))::integer AS fail_count,
    trunc((((count(*) FILTER (WHERE (ok = true)))::numeric / (NULLIF(count(*), 0))::numeric) * 100.0), 2) AS uptime_percent,
    trunc((avg(latency_ms))::numeric, 2) AS avg_latency_ms,
    trunc((min(latency_ms))::numeric, 2) AS min_latency_ms,
    trunc((max(latency_ms))::numeric, 2) AS max_latency_ms,
    (array_agg(ok ORDER BY ts DESC))[1] AS latest_ok,
    (array_agg(error ORDER BY ts DESC))[1] AS latest_error
   FROM public.health_entry h
  WHERE (service = ANY (ARRAY['websocket'::text, 'redis'::text, 'tus'::text, 'database'::text, 'keycloak'::text]))
  GROUP BY (date_trunc('hour'::text, ts)), service
  WITH NO DATA;


