    name text CONSTRAINT videos_name_not_null NOT NULL,
    active boolean DEFAULT true CONSTRAINT videos_active_not_null NOT NULL,
    id uuid DEFAULT uuidv7() CONSTRAINT videos_id_v7_not_null NOT NULL,
    description text CONSTRAINT videos_description_not_null NOT NULL,
    generated boolean DEFAULT false CONSTRAINT videos_generated_not_null NOT NULL,
    mcp boolean DEFAULT false CONSTRAINT videos_mcp_not_null NOT NULL
);


--
-- Name: videos_videos_connection; Type: TABLE; Schema: public; Owner: -
--

